const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Find all flights from LAX that are available on 2026-09-09
// and all flights to JFK that are available on 2026-09-09
// where leg1.destination == leg2.origin (the connecting airport)

const allFlights = db.prepare('SELECT * FROM flights WHERE source_skill = ?').all('tau2Airline');

// Filter flights available on 2026-09-09
function availableOn(flight, date) {
  try {
    const dates = JSON.parse(flight.dates_json);
    return dates[date] && dates[date].status === 'available';
  } catch(e) { return false; }
}

function getEconomyPrice(flight, date) {
  try {
    const dates = JSON.parse(flight.dates_json);
    if (dates[date] && dates[date].prices && dates[date].prices.economy !== undefined) {
      return dates[date].prices.economy;
    }
    const prices = JSON.parse(flight.cabin_prices_json);
    return prices.economy || null;
  } catch(e) { return null; }
}

function getSeats(flight, date) {
  try {
    const dates = JSON.parse(flight.dates_json);
    if (dates[date] && dates[date].available_seats && dates[date].available_seats.economy !== undefined) {
      return dates[date].available_seats.economy;
    }
    return 'N/A';
  } catch(e) { return 'N/A'; }
}

const date = '2026-09-09';

// Leg 1: from LAX to some connection point, available on date
const leg1s = allFlights.filter(f => f.origin === 'LAX' && f.destination !== 'JFK' && availableOn(f, date));

// Leg 2: from some connection point to JFK, available on date
const leg2s = allFlights.filter(f => f.destination === 'JFK' && f.origin !== 'LAX' && availableOn(f, date));

console.log('Leg1 (LAX -> ???) count:', leg1s.length);
console.log('Leg2 (??? -> JFK) count:', leg2s.length);
console.log('Leg1 destinations:', [...new Set(leg1s.map(f => f.destination))]);
console.log('Leg2 origins:', [...new Set(leg2s.map(f => f.origin))]);

// Find matching pairs
const results = [];
for (const l1 of leg1s) {
  for (const l2 of leg2s) {
    if (l1.destination === l2.origin) {
      results.push({
        leg1: {
          flight_id: l1.flight_id,
          origin: l1.origin,
          destination: l1.destination,
          departure: l1.departure_time,
          arrival: l1.arrival_time,
          economy_price: getEconomyPrice(l1, date),
          economy_seats: getSeats(l1, date),
          status: l1.status
        },
        leg2: {
          flight_id: l2.flight_id,
          origin: l2.origin,
          destination: l2.destination,
          departure: l2.departure_time,
          arrival: l2.arrival_time,
          economy_price: getEconomyPrice(l2, date),
          economy_seats: getSeats(l2, date),
          status: l2.status
        },
        connection: l1.destination,
        total_economy_price: (getEconomyPrice(l1, date) || 0) + (getEconomyPrice(l2, date) || 0)
      });
    }
  }
}

console.log('\\nTotal one-stop routes found:', results.length);
console.log(JSON.stringify(results, null, 2));
"

