const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const allFlights = db.prepare('SELECT * FROM flights').all();

const date = '2026-09-10';

function getDateInfo(flight, date) {
  try {
    const dates = JSON.parse(flight.dates_json);
    return dates[date] || null;
  } catch(e) { return null; }
}

function availableOn(f, d) {
  const info = getDateInfo(f, d);
  return info && info.status === 'available';
}

// Leg 1: LAX -> SFO on Sep 10
const leg1s = allFlights.filter(f => f.origin === 'LAX' && f.destination === 'SFO' && availableOn(f, date));
// Leg 2: SFO -> SEA on Sep 10
const leg2s = allFlights.filter(f => f.origin === 'SFO' && f.destination === 'SEA' && availableOn(f, date));

console.log('=== LEG 1: LAX -> SFO on', date, '===');
for (const f of leg1s) {
  const info = getDateInfo(f, date);
  console.log(JSON.stringify({
    flight_id: f.flight_id,
    departure: f.departure_time,
    arrival: f.arrival_time,
    prices: info.prices,
    seats: info.available_seats,
    source: f.source_skill
  }, null, 2));
}

console.log('\\n=== LEG 2: SFO -> SEA on', date, '===');
for (const f of leg2s) {
  const info = getDateInfo(f, date);
  console.log(JSON.stringify({
    flight_id: f.flight_id,
    departure: f.departure_time,
    arrival: f.arrival_time,
    prices: info.prices,
    seats: info.available_seats,
    source: f.source_skill
  }, null, 2));
}

// Build combinations with economy pricing
console.log('\\n=== ONE-STOP COMBINATIONS (Economy) ===');
let idx = 1;
for (const l1 of leg1s) {
  const i1 = getDateInfo(l1, date);
  const p1 = i1.prices.economy;
  if (p1 === undefined) continue;
  for (const l2 of leg2s) {
    const i2 = getDateInfo(l2, date);
    const p2 = i2.prices.economy;
    if (p2 === undefined) continue;
    console.log('Option ' + idx + ':');
    console.log('  Leg 1:', l1.flight_id, 'LAX', l1.departure_time, '->', 'SFO', l1.arrival_time, '| Economy: \$' + p1, '| Seats:', (i1.available_seats && i1.available_seats.economy) || 'N/A');
    console.log('  Leg 2:', l2.flight_id, 'SFO', l2.departure_time, '->', 'SEA', l2.arrival_time, '| Economy: \$' + p2, '| Seats:', (i2.available_seats && i2.available_seats.economy) || 'N/A');
    console.log('  Total Economy Price: \$' + (p1 + p2));
    console.log('');
    idx++;
  }
}
"
